/**
 * Request Lifecycle Module
 *
 * Manages request tracking, performance timing, and metrics.
 * Handles the start/end lifecycle of request processing.
 *
 * @module server/runtime-handler/request-lifecycle
 */
import { endRequest, isEnabled as isPerfEnabled, startRequest, startTimer, timeAsync, } from "../../utils/index.js";
import { metrics } from "../../observability/index.js";
import { endRequestMetrics, startRequestMetrics, } from "../../platform/adapters/fs/veryfront/read-operations.js";
import { requestTracker } from "./request-tracker.js";
import { generateRequestId } from "../../utils/request-id.js";
import { completeOnResponseBodyConsumption, completeOnResponseBodySettlement, isEventStreamResponse, } from "../../platform/compat/http/response-lifecycle.js";
/**
 * Start request lifecycle tracking.
 * Returns context needed to properly end the lifecycle.
 */
export function startRequestLifecycle(req, _pathname, isLightweight) {
    const incomingId = req.headers.get("x-request-id");
    const perfEnabled = isPerfEnabled();
    const perfRequestId = perfEnabled ? generateRequestId(incomingId) : undefined;
    if (perfRequestId)
        startRequest(perfRequestId);
    const stopTotal = startTimer("total");
    const requestId = generateRequestId(incomingId);
    const shouldCheckIsolation = !isLightweight;
    return {
        requestId,
        perfRequestId,
        stopTotal,
        shouldCheckIsolation,
    };
}
/**
 * Start tracking a request in the request tracker. Returns the tracking key to
 * pass to the completion helpers; it equals `requestId` unless a request with
 * the same id is already in flight.
 */
export function startRequestTracking(requestId, projectSlug, pathname, method, environment, releaseId, productionRuntime = false) {
    return requestTracker.start(requestId, projectSlug, pathname, method, environment, releaseId, productionRuntime);
}
/**
 * Start per-request content metrics tracking.
 */
export function startContentMetrics() {
    startRequestMetrics();
}
/**
 * End per-request content metrics tracking.
 */
export function endContentMetrics(info) {
    endRequestMetrics(info);
}
/**
 * Complete request tracking and record completion status.
 */
export function completeRequestTracking(requestId, status, isTimeout, profile) {
    requestTracker.complete(requestId, status, isTimeout, profile);
}
/**
 * Keep streaming responses in the shutdown drain set until their body settles.
 * Handler completion only means response headers are ready; HTML and SSE bodies
 * can continue producing content after that point.
 */
export function completeRequestTrackingOnResponseEnd(requestId, response, isTimeout, profile, handlerSettled, settleResponseBody = false) {
    if (isTimeout && handlerSettled) {
        void handlerSettled.then(() => completeRequestTracking(requestId, response.status, true, profile), () => completeRequestTracking(requestId, response.status, true, profile));
        return response;
    }
    if (!response.body) {
        completeRequestTracking(requestId, response.status, isTimeout, profile);
        return response;
    }
    requestTracker.markLongLived(requestId);
    const settle = () => {
        completeRequestTracking(requestId, response.status, isTimeout, profile);
    };
    if (settleResponseBody) {
        return completeOnResponseBodyConsumption(response, settle, undefined, { highWaterMark: 0 }, {
            waitForConsumption: true,
        });
    }
    return isEventStreamResponse(response)
        ? completeOnResponseBodySettlement(response, settle)
        : completeOnResponseBodyConsumption(response, settle, undefined, { highWaterMark: 0 }, {
            waitForConsumption: true,
        });
}
/**
 * End request lifecycle tracking.
 */
export function endRequestLifecycle(ctx) {
    ctx.stopTotal();
    if (ctx.perfRequestId)
        endRequest(ctx.perfRequestId);
}
/**
 * Increment the request metrics counter.
 */
export async function incrementRequestMetrics() {
    await timeAsync("metrics:inc-request", () => metrics.incRequest());
}
// Re-export timeAsync for handler use
export { timeAsync };
